"""Read-only recomputation and separately graded results; never solve/retry."""
from analysis.lps_pvce_v2.common import *
import csv,subprocess,importlib.metadata as md

def main():
 ca=json.loads((BASE/'CONTINUUM_REFERENCE_AUDIT.json').read_text());ss=json.loads((BASE/'A0_FIRST_FAILURE_SEARCH.json').read_text());v1=json.loads((OLD/'PVCE_ENERGY_RELEASE_RESULTS.json').read_text());rows=[]
 for kind,obj in [('LPS_V1',v1)]+[(f'FEM_{k}',v) for k,v in ca['levels'].items()]:
  U=obj['U_J'] if kind=='LPS_V1' else [s['U_J'] for s in obj['states']];rows.append(dict(model=kind,U0_J=U[0],U1_J=U[1],U2_J=U[2],G_two_J_m2=(U[0]-U[1])/3e-8,G_three_J_m2=(3*U[0]-4*U[1]+U[2])/6e-8))
 for r in rows:r['LPS_minus_reference_over_reference_three']=rows[0]['G_three_J_m2']/r['G_three_J_m2']-1
 with (BASE/'CONTINUUM_PVCE_COMPARISON.csv').open('w') as fp:w=csv.DictWriter(fp,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 fem=[s for v in ca['levels'].values() for s in v['states']];lps=[json.loads(p.read_text()) for p in sorted((BASE/'lps').glob('*/RESULT.json'))];checks=[]
 for r in lps:
  z=np.load(BASE/'lps'/r['name']/'equilibrium.npz');g,e,a,mask,lo,hi,*_=model([-100e-6,-50e-6,0][int(r['case'][-1])]);U,f=e.eval(np.ascontiguousarray(z['x_m']),a,True);rr=risk(z);old=np.load(OLD/r['case']/'reference.npz');assert np.array_equal(a,old['alive']) and np.array_equal(e.m,old['m']) and np.array_equal(e.b,old['bonds']);assert abs(U-r['U_J'])<1e-25;assert np.max(abs(f-z['independent_force_N']))<1e-25
  assert abs((z['x_m'][hi,2]-g['X'][hi,2]).mean()-(z['x_m'][lo,2]-g['X'][lo,2]).mean()-r['opening_m'])<1e-18
  checks.append(dict(case=r['name'],energy_recomputed_exact=True,force_recomputed_exact=True,common_m_unchanged=True,full_reference_ids_unchanged=True,opening_exact=True,maximum_stretch_recomputed=rr['max_stretch'],accepted=r['accepted']))
 # Extra read-only face/edge independence: matching geometric DOFs on opposing slit must have different global indices except the front.
 facechecks=[]
 for level in ca['levels']:
  for case in ['A0','A1','A2']:
   z=np.load(BASE/'continuum'/level/case/'equilibrium.npz');X=z['vertices_m'];t=z['tetrahedra'];pair=z['split_original'];du=z['split_duplicate'];nd=z['nodal_dofs'];assert len(set(nd[:,pair].ravel())&set(nd[:,du].ravel()))==0;assert np.array_equal(X[pair],X[du]);assert (z['crack_vertex_gap_m']>=-1e-12).all();assert len(z['gauge_dofs'])==3
   facechecks.append(dict(level=level,case=case,duplicated_coincident_vertices=len(pair),distinct_displacement_dofs=True,crack_gap_positive=True,minimal_transverse_gauges=3))
 candidate=lps[-1];scale=candidate['opening_m']/2e-6;Uquad=v1['U_J'][0]*scale**2;scaling=dict(kind='A0_ENERGY_ONLY_UNACCEPTED_HIGH_CANDIDATE',opening_m=candidate['opening_m'],candidate_U_J=candidate['U_J'],quadratic_extrapolated_A0_U_J=Uquad,relative_difference=candidate['U_J']/Uquad-1,stretch_relative_difference=candidate['risk']['max_stretch']/(ss['samples'][0]['risk']['max_stretch']*scale)-1,G_high_actual=None,G_high_vs_quadratic_difference=None,scope='A0 candidate energy comparison only; not a new high-load PVCE G and not an accepted equilibrium result.')
 # Mixed volumetric projection diagnostic prevents overclaiming mesh convergence even if G increment is stable.
 projection={level:[r['primal_vs_mixed_energy_relative'] for r in ca['levels'][level]['states']] for level in ca['levels']}
 status=dict(CONTINUUM_REFERENCE_VALIDITY=ca['status'],CONTINUUM_MESH_SCOPE=ca['mesh_scope']+'; MIXED_VOLUMETRIC_FIELD_RESOLUTION_NOT_CERTIFIED',LOW_LOAD_PVCE_COMPARISON='FINITE_MESH_MIXED_CONTINUUM_REFERENCE_WITH_EXPLICIT_MAPPING_LIMITS',A0_FIRST_FAILURE_LOCATION='UNDETERMINED; UNACCEPTED_CANDIDATE_MAXIMUM_AT_GRIP',A0_CRITICAL_OPENING_SCOPE='NOT_BRACKETED_STOPPED_AT_FROZEN_STATIC_GATE',NEAR_ONSET_STATIC_EQUILIBRIUM='FAILED_ABSOLUTE_RESIDUAL_FORCE_GATE',NEAR_ONSET_PVCE_G_DRIVE='NOT_RUN_STATIC_ADMISSION_FAILED',LINEAR_SCALING_VALIDITY='NOT_VALIDATED_FOR_HIGH_G; A0_UNACCEPTED_ENERGY_DIAGNOSTIC_ONLY',MATERIAL_GC='NOT_IDENTIFIED',PRODUCTION_PARAMETERS_UNCHANGED=None,DOCUMENT_UPDATE='PENDING')
 save(BASE/'FINAL_STATUS.json',status)
 save(BASE/'ENERGY_AND_EQUILIBRIUM_AUDIT.json',dict(continuum=fem,lps=lps,comparison=rows,scaling=scaling,mixed_projection_energy_excess=projection,static_error='FEM residual/work balance checked; LPS empirical residual-work estimate is not a rigorous bound. Candidate misses1e-13N absolute gate despite relative gate passing. This is numerical acceptance failure, not proof of physical instability.',finite_increment_error='Two-vs-three differences are not spatial convergence.',model_error='Only one dx/horizon; internal-plane continuum vs nodal half-cells, nonlocal boundary, crack singularity and finite geometric response remain unseparated. Mixed volumetric projection remains substantial and is disclosed; this is a finite-mesh benchmark, not certified continuum exact solution.'))
 protected=json.loads((BASE/'provenance/PROTECTED_START.json').read_text());changed=[p for p,h in protected.items() if sha(ROOT/p)!=h];assert not changed;save(BASE/'provenance/PROTECTED_FINAL.json',dict(checked=len(protected),changed=changed))
 before=json.loads((BASE/'provenance/ENVIRONMENT_BEFORE.json').read_text())['packages'];after={d.metadata['Name']:d.version for d in md.distributions()};assert before==after;save(BASE/'provenance/ENVIRONMENT_DIFF.json',dict(base_environment_unchanged=True,private_addition='scikit-fem12.0.2 in /workspace/y_clot/envs/pvce_v2_packages only',packages_after=after))
 attemptsA=list((BASE/'continuum').glob('*/*/ATTEMPT.json'));attemptsB=list((BASE/'lps').glob('*/ATTEMPT.json'));assert len(attemptsA)<=6 and len(attemptsB)<=8
 resource=dict(FEM_static_attempts=len(attemptsA),LPS_static_attempts=len(attemptsB),LPS_accepted_new=sum(r['accepted'] for r in lps),old_V1_states_reused=3,native_baseline_force_only_checks=2,no_repeated_equilibria=True,FEM_case_wall_seconds_sum=sum(r['wall_seconds'] for r in fem),FEM_cpu_seconds_sum=sum(r['cpu_seconds'] for r in fem),LPS_case_wall_seconds_sum=sum(r['wall_seconds'] for r in lps),LPS_cpu_seconds_sum=sum(r['cpu_seconds'] for r in lps),peak_single_process_RSS_MiB=max(r['peak_RSS_MiB'] for r in fem+lps),GPU=False,threads_per_process=1,maximum_active_solver_processes=2,FEM_final_process_wall_seconds=ca['wall_seconds'],stop='Six FEM states completed; one LPS candidate failed frozen absolute force gate; no high A1/A2; no automatic next task.')
 save(BASE/'RUN_RESOURCES.json',resource)
 save(BASE/'IMPLEMENTATION_CHECKS.json',dict(LPS_readonly_recomputation=checks,FEM_face_checks=facechecks,protected_files_unchanged=len(protected),no_production_change=True,native_source_criterion='bond_bpm_peri.cpp: allow_breaks && stretch > s0; alpha0 makes s0=s00=.15; static break no only suppresses deletion in new adapter',native_adapter_diff='V1 Native implementation body differs only in bond_style bpm/peri break no; finite native-force/gradient check proves force unaffected in accepted baseline and new candidate.',budgets=resource,numerical_issue='L-BFGS-B stopped at zero/roundoff relative objective reduction (ftol0) before maximum absolute residual<1e-13N. Stored native and independent force independently confirm1.129107e-12N. No tolerance relaxation/restart.',postprocess_fixes=json.loads((BASE/'provenance/POSTPROCESS_FIXES.json').read_text())))
 status['PRODUCTION_PARAMETERS_UNCHANGED']=True;save(BASE/'FINAL_STATUS.json',status)
 print(json.dumps(dict(comparison=rows,refinement=ca['relative_G_change'],projection=projection,scaling=scaling,resources=resource),indent=2))
if __name__=='__main__':main()
